import * as Sentry from '@sentry/node';

// No-op when SENTRY_DSN is unset (local dev, tests).
Sentry.init({
  dsn: process.env.SENTRY_DSN,
  environment: process.env.NODE_ENV || 'development',
  release: process.env.SENTRY_RELEASE,
  tracesSampleRate: Number(process.env.SENTRY_TRACES_SAMPLE_RATE || 0),
});

import './instrument.js'; // must be first so Sentry can hook other modules
import * as Sentry from '@sentry/node';
import express from 'express';
import { listsForHousehold } from './lists.js';

const app = express();
app.use(express.json());

// Express 5 forwards rejected async handlers to the error middleware.
app.get('/households/:id/lists', async (req, res) => {
  res.json(await listsForHousehold(req.params.id));
});

// After all routes, before any other error middleware.
Sentry.setupExpressErrorHandler(app);

app.use((err, req, res, next) => {
  if (res.headersSent) return next(err);
  res.status(500).json({ error: 'Internal Server Error' });
});

app.listen(process.env.PORT || 3000);
